const requests=new WeakMap();
export async function displayNetworkFee(element,asset,network){if(!element)return;const request={};requests.set(element,request);element.textContent='Checking live network fees…';try{const response=await fetch('/api/network-fees?asset='+encodeURIComponent(asset)+'&network='+encodeURIComponent(network),{signal:AbortSignal.timeout(16000)});if(!response.ok)throw Error();const q=await response.json();if(!element.isConnected||requests.get(element)!==request)return;if(Date.now()>Date.parse(q.expiresAt)||!Number.isFinite(q.rate)||q.rate<=0)throw Error();const rate=q.rate.toLocaleString('en-US',{maximumFractionDigits:9});const total=q.estimatedNative===null?'Total depends on your wallet':('Approx. '+q.estimatedNative.toLocaleString('en-US',{maximumFractionDigits:12})+' '+q.nativeAsset+(q.estimatedUsd!==null?' (≈ $'+q.estimatedUsd.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:4})+')':''));element.textContent=total+' · '+rate+' '+q.rateUnit+(q.bandwidthRate?' · '+q.bandwidthRate+' TRX / bandwidth byte':'')+'. '+q.assumption+' Source: '+q.source+(q.usdSource?' / '+q.usdSource:'')+' · '+new Date(q.observedAt).toLocaleTimeString()+'. Network estimates are not charged by Aurex.';setTimeout(()=>{if(element.isConnected&&requests.get(element)===request)element.textContent='This network estimate has expired. Re-select the network to refresh; your wallet determines the actual fee.';},Math.max(0,Date.parse(q.expiresAt)-Date.now()));}catch{if(element.isConnected&&requests.get(element)===request)element.textContent='Live estimate unavailable. Your sending wallet determines the actual network fee.';}}
